select count(*) as "count" from (select 1 from (select (CASE WHEN ("occurrences"."region" = ?) THEN "occurrences"."id" END) AS "id", (CASE WHEN ("occurrences"."region" = ?) THEN st_astext("occurrences"."geometry") END) AS "geometry" from "occurrences" where "occurrences"."region" = ? and ("occurrences"."geometry" && ST_MakeEnvelope(?, ?, ?, ?, ?)) and ST_DWithin("occurrences"."geometry"::geography, ST_SetSRID(ST_MakePoint(?, ?), 4326)::geography, ?)) as "p" where "p"."geometry" is not null) as "c"
